// Day window for Africa/Cairo with correct offset in the output.
// Same shape as Create Date Range2 in the per-lecture workflows.
const TZ = 'Africa/Cairo';

function partsInTz(d, tz=TZ){
  const fmt = new Intl.DateTimeFormat('en-GB',{
    timeZone: tz, year:'numeric', month:'2-digit', day:'2-digit',
    hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false
  });
  const obj = Object.fromEntries(fmt.formatToParts(d).map(p=>[p.type,p.value]));
  return { yyyy: obj.year, mm: obj.month, dd: obj.day };
}

function tzOffsetHHMM(date, tz=TZ){
  const utc = new Date(Date.UTC(
    date.getFullYear(), date.getMonth(), date.getDate(),
    date.getHours(), date.getMinutes(), date.getSeconds(), date.getMilliseconds()
  ));
  const inTz = new Date(utc.toLocaleString('en-US',{ timeZone: tz }));
  const offMin = Math.round((inTz - utc)/60000);
  const sign = offMin >= 0 ? '+' : '-';
  const a = Math.abs(offMin);
  const H = String(Math.floor(a/60)).padStart(2,'0');
  const M = String(a%60).padStart(2,'0');
  return `${sign}${H}:${M}`;
}

const now = new Date();
const { yyyy, mm, dd } = partsInTz(now, TZ);


const startLocal = new Date(`${yyyy}-${mm}-${dd}T00:00:00`);
const off = tzOffsetHHMM(startLocal, TZ);

return [{
  json: {
    targetDate:   `${yyyy}-${mm}-${dd}`,
    today:        `${yyyy}-${mm}-${dd}T00:00:00${off}`,
    todayPlusOne: `${yyyy}-${mm}-${dd}T23:59:59${off}`
  }
}];

if (!items[0].json.value || !Array.isArray(items[0].json.value)) {
  return [];
}

return items[0].json.value.map(e => ({
  json: {
    attendees: e.attendees || null,
    subject: e.subject || null,
    meetingStart: e.start?.dateTime || null,
    meetingEnd: e.end?.dateTime || null,
    joinUrl: e.onlineMeeting?.joinUrl || null,
    bodyPreview: e.bodyPreview || null,
  }
}));

const SRC_NODE = "Extract Calendar Fields";

return items.map((it, idx) => {
  const meeting = (it.json.value || [])[0] || {};

  const pIndex = it.pairedItem?.item ?? idx;
  const src = $items(SRC_NODE)[pIndex]?.json || {};

  return {
    json: {
      subject: src.subject || meeting.subject || null,
      meetingStart: src.meetingStart || null,
      meetingEnd: src.meetingEnd || null,
      joinUrl: src.joinUrl || null,
      meetingId: meeting.id || ""
    },
    pairedItem: { item: pIndex }
  };
});

// Match each Teams calendar event to one active Aptem group.
function normalizeGroup(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

const groupItems = $items("Get Active Groups") || [];
const groupLookup = new Map();
for (const item of groupItems) {
  const original = item?.json?.group_name;
  const normalized = normalizeGroup(original);
  if (original && normalized) groupLookup.set(normalized, original);
}

const evaluated = items.map(item => {
  const event = item.json || {};
  const normalizedSubject = normalizeGroup(event.subject);
  const module = groupLookup.get(normalizedSubject) || null;
  const matched = Boolean(module && event.meetingId);
  return {
    ...event,
    matched,
    module,
    targetDate: String(event.meetingStart || '').slice(0, 10),
    scheduledStart: event.meetingStart || '',
    scheduledEnd: event.meetingEnd || '',
    matchReason: matched
      ? 'normalized subject equals active Aptem group'
      : !event.meetingId ? 'missing meetingId' : 'no active group match'
  };
});

const matchedCount = evaluated.filter(row => row.matched).length;
const summary = {
  total_calendar_events: evaluated.length,
  total_active_groups: groupLookup.size,
  matched_count: matchedCount,
  unmatched_count: evaluated.length - matchedCount
};

return evaluated.map(row => ({ json: { ...row, _summary: summary } }));

// Recording v9: derive each lecture's exact Teams call id, and decide whether it
// can be looked up at all.
//
// qa_doctors_sessions.session_id is the raw Graph transcript id. It is NOT
// plain base64 text: it is base64url(MessagePack-CSharp LZ4 envelope). v8
// decoded it as UTF-8 and regex-searched for a GUID, which fails whenever the
// LZ4 block uses a back-reference inside the GUID. This is a strict port of
// the QA Core RC4 decoder (app/transcripts/identity.py): an id that does not
// decode completely and exactly yields NO call id - never a guess.

const MAX_ENCODED_BYTES = 4096;
const MAX_DECODED_BYTES = 16384;
const LZ4_BLOCK_EXT_TYPE = 98;
const SUPPORTED_FORMAT_VERSION = 4;
const TRANSCRIPT_ID = /^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})-\d+-TranscriptV2$/i;

class IdentityDecodeError extends Error {}
class MpExt { constructor(type, data) { this.type = type; this.data = data; } }
class MpFloat { constructor(value) { this.value = value; } }

function fail(message) { throw new IdentityDecodeError(message); }

function base64url(text) {
  if (text.length > MAX_ENCODED_BYTES * 2) fail('id is implausibly long');
  const body = text.replace(/-/g, '+').replace(/_/g, '/').replace(/=+$/, '');
  if (!/^[A-Za-z0-9+/]*$/.test(body) || body.length % 4 === 1) fail('not base64url');
  const data = Buffer.from(body + '='.repeat((4 - (body.length % 4)) % 4), 'base64');
  if (!data.length || data.length > MAX_ENCODED_BYTES) fail('decoded length out of range');
  return data;
}

function lz4Length(src, i, value) {
  for (;;) {
    if (i >= src.length) fail('LZ4 length truncated');
    const byte = src[i++];
    value += byte;
    if (byte !== 255) return [value, i];
  }
}

function lz4BlockDecompress(src, expectedSize) {
  if (expectedSize > MAX_DECODED_BYTES) fail('block too large');
  const dst = [];
  let i = 0;
  const n = src.length;
  for (;;) {
    if (i >= n) fail('LZ4 block truncated before a token');
    const token = src[i++];
    let literal = token >> 4;
    if (literal === 15) [literal, i] = lz4Length(src, i, literal);
    if (i + literal > n) fail('LZ4 literal run past end of block');
    for (let k = 0; k < literal; k++) dst.push(src[i + k]);
    i += literal;
    if (dst.length > expectedSize) fail('LZ4 output exceeds declared size');
    if (i === n) break;
    if (i + 2 > n) fail('LZ4 match offset truncated');
    const offset = src[i] | (src[i + 1] << 8);
    i += 2;
    if (offset === 0 || offset > dst.length) fail('LZ4 match offset out of range');
    let match = token & 0x0f;
    if (match === 15) [match, i] = lz4Length(src, i, match);
    match += 4;
    if (dst.length + match > expectedSize) fail('LZ4 output exceeds declared size');
    const start = dst.length - offset;
    for (let k = 0; k < match; k++) dst.push(dst[start + k]);
  }
  if (dst.length !== expectedSize) fail('LZ4 produced the wrong number of bytes');
  return Buffer.from(dst);
}

function take(data, i, count) {
  if (count < 0 || i + count > data.length) fail('MessagePack value truncated');
  return [data.subarray(i, i + count), i + count];
}

function uint(data, i, size) {
  const [raw, next] = take(data, i, size);
  let value = 0;
  for (const byte of raw) value = value * 256 + byte;
  return [value, next];
}

function str(data, i, size) {
  const [raw, next] = take(data, i, size);
  const text = raw.toString('utf8');
  if (!Buffer.from(text, 'utf8').equals(raw)) fail('invalid UTF-8 in string');
  return [text, next];
}

function ext(data, i, size) {
  const [raw, afterType] = take(data, i, 1);
  const type = raw[0] > 127 ? raw[0] - 256 : raw[0];
  const [payload, next] = take(data, afterType, size);
  return [new MpExt(type, payload), next];
}

function array(data, i, size, depth) {
  if (size > data.length) fail('array length exceeds input');
  const values = [];
  for (let k = 0; k < size; k++) {
    let value;
    [value, i] = read(data, i, depth + 1);
    values.push(value);
  }
  return [values, i];
}

function map(data, i, size, depth) {
  if (size > data.length) fail('map length exceeds input');
  const pairs = [];
  for (let k = 0; k < size; k++) {
    let key, value;
    [key, i] = read(data, i, depth + 1);
    [value, i] = read(data, i, depth + 1);
    pairs.push([key, value]);
  }
  return [pairs, i];
}

function read(data, i, depth) {
  if (depth > 16) fail('MessagePack nesting too deep');
  const [raw, next] = take(data, i, 1);
  const b = raw[0];
  i = next;
  if (b <= 0x7f) return [b, i];
  if (b >= 0xe0) return [b - 0x100, i];
  if (b >= 0xa0 && b <= 0xbf) return str(data, i, b & 0x1f);
  if (b >= 0x90 && b <= 0x9f) return array(data, i, b & 0x0f, depth);
  if (b >= 0x80 && b <= 0x8f) return map(data, i, b & 0x0f, depth);
  if (b === 0xc0) return [null, i];
  if (b === 0xc2) return [false, i];
  if (b === 0xc3) return [true, i];
  if (b >= 0xc4 && b <= 0xc6) {
    const [size, at] = uint(data, i, { 0xc4: 1, 0xc5: 2, 0xc6: 4 }[b]);
    return take(data, at, size);
  }
  if (b >= 0xc7 && b <= 0xc9) {
    const [size, at] = uint(data, i, { 0xc7: 1, 0xc8: 2, 0xc9: 4 }[b]);
    return ext(data, at, size);
  }
  if (b === 0xca || b === 0xcb) {
    const [bytes, at] = take(data, i, b === 0xca ? 4 : 8);
    return [new MpFloat(b === 0xca ? bytes.readFloatBE(0) : bytes.readDoubleBE(0)), at];
  }
  if (b >= 0xcc && b <= 0xcf) return uint(data, i, 1 << (b - 0xcc));
  if (b >= 0xd0 && b <= 0xd3) {
    const size = 1 << (b - 0xd0);
    const [bytes, at] = take(data, i, size);
    let value = 0n;
    for (const byte of bytes) value = (value << 8n) | BigInt(byte);
    if (bytes[0] & 0x80) value -= 1n << BigInt(size * 8);
    return [Number(value), at];
  }
  if (b >= 0xd4 && b <= 0xd8) return ext(data, i, 1 << (b - 0xd4));
  if (b >= 0xd9 && b <= 0xdb) {
    const [size, at] = uint(data, i, { 0xd9: 1, 0xda: 2, 0xdb: 4 }[b]);
    return str(data, at, size);
  }
  if (b === 0xdc || b === 0xdd) {
    const [size, at] = uint(data, i, b === 0xdc ? 2 : 4);
    return array(data, at, size, depth);
  }
  if (b === 0xde || b === 0xdf) {
    const [size, at] = uint(data, i, b === 0xde ? 2 : 4);
    return map(data, at, size, depth);
  }
  fail('reserved MessagePack byte');
}

function unpackExactly(data) {
  const [value, end] = read(data, 0, 0);
  if (end !== data.length) fail('trailing bytes after MessagePack value');
  return value;
}

function unpackSequence(data) {
  const values = [];
  let i = 0;
  while (i < data.length) {
    let value;
    [value, i] = read(data, i, 0);
    values.push(value);
  }
  return values;
}

const isInt = value => typeof value === 'number' && Number.isInteger(value);

function unwrapEnvelope(outer) {
  if (!Array.isArray(outer) || outer.length < 2) fail('not an LZ4 envelope');
  const header = outer[0];
  if (!(header instanceof MpExt) || header.type !== LZ4_BLOCK_EXT_TYPE) {
    fail('missing LZ4 extension header');
  }
  const lengths = unpackSequence(header.data);
  const blocks = outer.slice(1);
  if (lengths.length !== blocks.length || !blocks.every(Buffer.isBuffer)) {
    fail('LZ4 header does not match its blocks');
  }
  if (!lengths.every(n => isInt(n) && n >= 0) ||
      lengths.reduce((a, b) => a + b, 0) > MAX_DECODED_BYTES) {
    fail('invalid uncompressed length');
  }
  return Buffer.concat(blocks.map((block, k) => lz4BlockDecompress(block, lengths[k])));
}

function fields(values) {
  if (!Array.isArray(values)) fail('payload is not an array');
  const trimmed = values.slice();
  while (trimmed.length && trimmed[trimmed.length - 1] === null) trimmed.pop();
  if (trimmed.length !== 4) fail('expected 4 fields');
  const [version, threadId, meetingTimestamp, transcriptId] = trimmed;
  const numeric = version instanceof MpFloat ? version.value : version;
  if (typeof numeric !== 'number' || numeric !== SUPPORTED_FORMAT_VERSION) {
    fail('unsupported format version');
  }
  for (const value of [threadId, meetingTimestamp, transcriptId]) {
    if (typeof value !== 'string' || !value.trim()) fail('identity field missing');
  }
  if (!threadId.includes('@thread')) fail('thread id is not a Teams thread');
  if (!/^\p{Nd}+$/u.test(meetingTimestamp)) fail('meeting timestamp is not numeric');
  return { thread_id: threadId, meeting_timestamp: meetingTimestamp, transcript_id: transcriptId };
}

function transcriptIdentity(rawId) {
  const text = rawId === null || rawId === undefined ? '' : String(rawId).trim();
  if (!text) return { source: 'RAW' };
  try {
    return { source: 'DECODED', ...fields(unpackExactly(unwrapEnvelope(unpackExactly(base64url(text))))) };
  } catch (error) {
    if (error instanceof IdentityDecodeError) return { source: 'RAW', decode_error: error.message };
    throw error;
  }
}

const settings = $items('Validate Run Settings')[0].json;
const blank = value => !String(value ?? '').trim();

return items.map((item, index) => {
  const lecture = item.json || {};
  const identity = transcriptIdentity(lecture.session_id);
  const callMatch = identity.source === 'DECODED'
    ? TRANSCRIPT_ID.exec(identity.transcript_id) : null;
  const expectedCallId = callMatch ? callMatch[1].toLowerCase() : null;

  const organizerCount = Number(lecture.organizer_count || 0);
  const organizerId = String(lecture.meeting_lookup_user_id || '').trim() || null;
  const cancelled = String(lecture.cancelled_session ?? '').trim().toLowerCase() === 'true';

  // Order matters: the first failing precondition is the reported reason.
  let precheck = null;
  if (cancelled) precheck = 'NO_RECORDING_EXPECTED_CANCELLED';
  else if (blank(lecture.meeting_id) || blank(lecture.session_id)) precheck = 'SESSION_IDENTITY_MISSING';
  else if (organizerCount > 1) precheck = 'ORGANIZER_LOOKUP_ID_AMBIGUOUS';
  else if (!organizerId) precheck = 'ORGANIZER_LOOKUP_ID_MISSING';
  else if (!expectedCallId) precheck = 'SESSION_CALL_ID_MISSING';

  return {
    json: {
      ...lecture,
      expected_call_id: expectedCallId,
      call_id_source: expectedCallId ? 'rc4_transcript_identity_v1' : null,
      transcript_identity_source: identity.source,
      meeting_lookup_user_id: organizerId,
      organizer_count: organizerCount,
      cancelled,
      precheck_status: precheck,
      graph_lookup_url: precheck ? null
        : 'https://graph.microsoft.com/v1.0/users/' + encodeURIComponent(organizerId) +
          '/onlineMeetings/' + encodeURIComponent(String(lecture.meeting_id).trim()) +
          '/recordings?$top=100',
      dry_run: settings.dry_run !== false,
      allow_overwrite_existing: false
    },
    pairedItem: { item: index }
  };
});

// Recording v9: classify each organizer-aware Graph recordings lookup.
//
// The HTTP node runs once per lecture that passed the precheck, in order, and
// continues on error, so response k belongs to lookup item k. A failed HTTP
// call (401/403/404/429/5xx/network) is GRAPH_LOOKUP_FAILED - it proves
// nothing about whether a recording exists. RECORDING_NOT_FOUND is reserved
// for a successful, complete Graph response with no recording for the call id.
const lectures = $items('Graph Lookup Possible?', 0, 0);

function httpStatus(error) {
  const direct = Number(error?.httpCode ?? error?.status ?? error?.statusCode);
  if (Number.isInteger(direct) && direct >= 100) return direct;
  const match = /^\s*(\d{3})\b/.exec(String(error?.message || ''));
  return match ? Number(match[1]) : null;
}

if (items.length !== lectures.length) {
  throw new Error(`Graph lookup returned ${items.length} responses for ${lectures.length} lectures`);
}

const result = items.map((item, index) => {
  const lecture = lectures[index]?.json || {};
  const response = item.json || {};
  const expected = String(lecture.expected_call_id || '').toLowerCase();
  const base = {
    ...lecture,
    graph_http_status: null,
    graph_recording_id: null,
    graph_created_at: null,
    graph_content_correlation_id: null,
    graph_recordings_returned: null
  };

  if (response.error) {
    return { ...base, graph_http_status: httpStatus(response.error), graph_status: 'GRAPH_LOOKUP_FAILED' };
  }
  if (!Array.isArray(response.value)) {
    return { ...base, graph_status: 'GRAPH_LOOKUP_FAILED', graph_failure: 'response_has_no_value_array' };
  }
  const recordings = response.value;
  if (response['@odata.nextLink']) {
    // A later page could hold a second recording for the same call.
    return { ...base, graph_recordings_returned: recordings.length, graph_status: 'GRAPH_RESULTS_INCOMPLETE' };
  }
  const matches = recordings.filter(recording =>
    String(recording?.callId || '').toLowerCase() === expected);

  let status = 'EXACT_GRAPH_RECORDING_FOUND';
  if (!expected) status = 'SESSION_CALL_ID_MISSING';
  else if (matches.length === 0) status = 'RECORDING_NOT_FOUND';
  else if (matches.length > 1) status = 'AMBIGUOUS_GRAPH_RECORDINGS';
  else if (!Number.isFinite(Date.parse(matches[0].createdDateTime || ''))) {
    status = 'GRAPH_RECORDING_TIMESTAMP_INVALID';
  }

  const exact = status === 'EXACT_GRAPH_RECORDING_FOUND' ? matches[0] : null;
  return {
    ...base,
    graph_recordings_returned: recordings.length,
    graph_recording_id: exact?.id || null,
    graph_created_at: exact?.createdDateTime || null,
    graph_content_correlation_id: exact?.contentCorrelationId || null,
    graph_status: status
  };
});

return [{ json: { lectures: result, lecture_count: result.length } }];

const lectures = Array.isArray($json.lectures) ? $json.lectures : [];
const dates = [...new Set(
  lectures
    .map(lecture => String(lecture.date || '').slice(0, 10))
    .filter(Boolean)
)].sort();

return dates.map((date, index) => {
  const compactDate = date.replace(/-/g, '');
  return {
    json: {
      date,
      compact_date: compactDate,
      search_body: {
        requests: [{
          entityTypes: ['driveItem'],
          query: {
            queryString: compactDate + ' "Meeting Recording" filetype:mp4'
          },
          from: 0,
          size: 500,
          fields: [
            'id',
            'name',
            'webUrl',
            'createdDateTime',
            'lastModifiedDateTime',
            'parentReference',
            'file'
          ]
        }]
      }
    },
    pairedItem: { item: index }
  };
});

const searchDates = $items('Build One Search per Lecture Date');
const files = [];

items.forEach((item, index) => {
  const response = item.json || {};
  const searchDate = searchDates[index]?.json?.date || null;
  const hits = (response.value || [])
    .flatMap(value => value?.hitsContainers || [])
    .flatMap(container => container?.hits || []);

  for (const hit of hits) {
    const resource = hit?.resource;
    if (!resource?.id || !resource?.name) continue;
    const driveId = resource?.parentReference?.driveId || null;
    if (!driveId) continue;
    files.push({
      id: resource.id,
      driveId,
      name: resource.name,
      webUrl: resource.webUrl || null,
      createdDateTime: resource.createdDateTime || null,
      lastModifiedDateTime: resource.lastModifiedDateTime || null,
      source: 'tenant_graph_search',
      search_date: searchDate
    });
  }
});

return [{ json: { tenant_search_files: files } }];

const teams = Array.isArray($json.value) ? $json.value : [];
if (!teams.length) {
  throw new Error(
    'No Teams returned. Reconnect the Microsoft credential with Team.ReadBasic.All.'
  );
}

return teams.map((team, index) => ({
  json: {
    team_id: team.id,
    team_name: team.displayName || null
  },
  pairedItem: { item: index }
}));

const teams = $items('Expand Teams');
const output = [];

items.forEach((item, index) => {
  const team = teams[index]?.json || {};
  const channels = Array.isArray(item.json?.value) ? item.json.value : [];
  for (const channel of channels) {
    if (!channel?.id) continue;
    output.push({
      json: {
        ...team,
        channel_id: channel.id,
        channel_name: channel.displayName || null,
        channel_type: channel.membershipType || null
      }
    });
  }
});

if (!output.length) {
  throw new Error(
    'No Teams channels returned. Reconnect the credential with Channel.ReadBasic.All.'
  );
}
return output;

const channels = $items('Expand All Channels');
const output = [];

items.forEach((item, index) => {
  const folder = item.json || {};
  const channel = channels[index]?.json || {};
  const driveId =
    folder?.parentReference?.driveId ||
    folder?.remoteItem?.parentReference?.driveId ||
    null;
  const folderId = folder?.id || folder?.remoteItem?.id || null;
  if (!driveId || !folderId) return;

  output.push({
    json: {
      ...channel,
      drive_id: driveId,
      channel_folder_id: folderId
    }
  });
});

if (!output.length) {
  throw new Error(
    'No channel file folders are accessible. The credential needs Files.Read.All.'
  );
}
return output;

const folders = $items('Prepare Channel Recording Folders');
const files = [];

items.forEach((item, index) => {
  const folder = folders[index]?.json || {};
  const children = Array.isArray(item.json?.value) ? item.json.value : [];
  for (const file of children) {
    if (!file?.id || !file?.file || !/\.mp4$/i.test(String(file.name || ''))) {
      continue;
    }
    files.push({
      id: file.id,
      driveId: file?.parentReference?.driveId || folder.drive_id || null,
      name: file.name,
      webUrl: file.webUrl || null,
      createdDateTime: file.createdDateTime || null,
      lastModifiedDateTime: file.lastModifiedDateTime || null,
      source: 'teams_channel_recordings_folder',
      team_id: folder.team_id || null,
      team_name: folder.team_name || null,
      channel_id: folder.channel_id || null,
      channel_name: folder.channel_name || null
    });
  }
});

return [{ json: { channel_recording_files: files } }];

// Recording v9: match every lecture to AT MOST one recording file.
//
// Unchanged from v8: exact Graph call-id linkage, exact normalized subject,
// exactly one candidate, ambiguous => no update.
// Added: the file must be named for the lecture's own date.
// Changed: the timestamp rule. A Teams file name carries the moment recording
// started on the client, which the audit measured 17-73 s BEFORE Graph's
// createdDateTime (and never after it). So the file may lead Graph by up to
// 120 s and may never trail it. The window is a constant, not a setting.
const MAX_FILE_LEAD_SECONDS = 120;
const MATCH_METHOD = 'exact_call_id_subject_timestamp_v9';

const lectures =
  $items('Collect Lectures and Exact Graph Times')[0]?.json?.lectures || [];
const tenantFiles =
  $items('Collect Tenant Search Candidates')[0]?.json?.tenant_search_files || [];
const channelFiles =
  $items('Collect All Channel Recording Files')[0]?.json?.channel_recording_files || [];
const oneDriveResponse = items[0]?.json || {};
const oneDriveFiles = (Array.isArray(oneDriveResponse.value) ? oneDriveResponse.value : [])
  .filter(file => file?.id && file?.file && /\.mp4$/i.test(String(file.name || '')))
  .map(file => ({
    id: file.id,
    driveId: file?.parentReference?.driveId || null,
    name: file.name,
    webUrl: file.webUrl || null,
    createdDateTime: file.createdDateTime || null,
    lastModifiedDateTime: file.lastModifiedDateTime || null,
    source: 'current_user_onedrive_recordings'
  }));

const deduped = new Map();
for (const file of [...tenantFiles, ...channelFiles, ...oneDriveFiles]) {
  if (!file?.id || !file?.driveId) continue;
  const key = String(file.driveId) + ':' + String(file.id);
  deduped.set(key, { ...(deduped.get(key) || {}), ...file });
}
const files = [...deduped.values()];

// Same subject normalization as v8 and QA One Lecture v8.
const normalizeSubject = value => String(value || '')
  .toLowerCase()
  .replace(/&amp;/g, '&')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .replace(/^(dr|doctor|prof|professor|mr|mrs|ms)\s+/, '')
  .replace(/[^a-z0-9]+/g, '');

function parseTeamsFilename(name) {
  const match = String(name || '').match(
    /^(.*)-(\d{8})_(\d{6})(?:UTC)?-Meeting Recording\.mp4$/i
  );
  if (!match) return null;
  const date = match[2];
  const time = match[3];
  const isoDate = date.slice(0, 4) + '-' + date.slice(4, 6) + '-' + date.slice(6, 8);
  const timestamp = Date.parse(isoDate + 'T' + time.slice(0, 2) + ':' +
    time.slice(2, 4) + ':' + time.slice(4, 6) + 'Z');
  if (!Number.isFinite(timestamp)) return null;
  return { subject: match[1], isoDate, timestamp };
}

const parsedFiles = files
  .map(file => ({ file, parsed: parseTeamsFilename(file.name) }))
  .filter(candidate => candidate.parsed);

return lectures.map((lecture, index) => {
  const lectureDate = String(lecture.lecture_date || lecture.date || '').slice(0, 10);
  const expectedSubject = normalizeSubject(lecture.subject);
  const graphTimestamp = Date.parse(lecture.graph_created_at || '');
  const graphExact = lecture.graph_status === 'EXACT_GRAPH_RECORDING_FOUND' &&
    Number.isFinite(graphTimestamp) && Boolean(expectedSubject) && Boolean(lectureDate);

  const assessed = graphExact ? parsedFiles.map(candidate => {
    const leadSeconds = (graphTimestamp - candidate.parsed.timestamp) / 1000;
    return {
      ...candidate,
      subject_exact: normalizeSubject(candidate.parsed.subject) === expectedSubject,
      same_date: candidate.parsed.isoDate === lectureDate,
      lead_seconds: leadSeconds,
      timestamp_ok: leadSeconds >= 0 && leadSeconds <= MAX_FILE_LEAD_SECONDS
    };
  }) : [];

  const exact = assessed
    .filter(c => c.subject_exact && c.same_date && c.timestamp_ok)
    .sort((a, b) => a.lead_seconds - b.lead_seconds);

  let status;
  if (!graphExact) status = lecture.graph_status || 'GRAPH_LOOKUP_FAILED';
  else if (exact.length > 1) status = 'AMBIGUOUS_RECORDING_FILES';
  else if (exact.length === 1) status = 'EXACT_RECORDING_FILE_MATCHED';
  else if (assessed.some(c => c.subject_exact && c.same_date)) status = 'TIMESTAMP_MISMATCH';
  else if (assessed.some(c => c.same_date && c.timestamp_ok)) status = 'SUBJECT_MISMATCH';
  else status = 'RECORDING_FILE_NOT_FOUND';

  const best = status === 'EXACT_RECORDING_FILE_MATCHED' ? exact[0] : null;
  const file = best?.file || null;
  const nearestSubjectLead = assessed
    .filter(c => c.subject_exact && c.same_date)
    .map(c => c.lead_seconds)
    .sort((a, b) => Math.abs(a) - Math.abs(b))[0];

  return {
    json: {
      ...lecture,
      recording_item_id: file?.id || null,
      recording_drive_id: file?.driveId || null,
      recording_filename: file?.name || null,
      recording_web_url: file?.webUrl || null,
      recording_source: file?.source || null,
      recording_team_name: file?.team_name || null,
      recording_channel_name: file?.channel_name || null,
      timestamp_difference_seconds: best ? best.lead_seconds : null,
      nearest_same_subject_lead_seconds: nearestSubjectLead ?? null,
      max_file_lead_seconds: MAX_FILE_LEAD_SECONDS,
      exact_file_matches: exact.length,
      candidate_files_seen: files.length,
      recording_match_method: best ? MATCH_METHOD : null,
      ambiguous_candidate_filenames: exact.length > 1
        ? exact.map(candidate => candidate.file?.name || null) : [],
      recording_link_status: status
    },
    pairedItem: { item: index }
  };
});

// Recording v9: dry-run report. Nothing downstream of this node writes.
return items.map((item, index) => ({
  json: {
    ...item.json,
    execution_result:
      item.json.recording_link_status === 'EXACT_RECORDING_FILE_MATCHED'
        ? 'DRY_RUN_EXACT_MATCH_NO_DATABASE_UPDATE'
        : 'DRY_RUN_UNMATCHED_NO_DATABASE_UPDATE'
  },
  pairedItem: { item: index }
}));

// Recording v9: choose the URL to persist for an exact match.
// Prefer the organization view link; fall back to the exact DriveItem webUrl,
// but never to a SharePoint list-form URL.
const matchedItems = $items('Exactly One Safe File?', 0, 0);

function pairedIndex(item, fallback) {
  const paired = item?.pairedItem;
  if (Array.isArray(paired)) {
    const value = Number(paired[0]?.item);
    if (Number.isInteger(value)) return value;
  }
  const value = Number(paired?.item);
  return Number.isInteger(value) ? value : fallback;
}

const usable = value => {
  const text = String(value || '').trim();
  return text && !/\/Forms\/DispForm\.aspx/i.test(text) ? text : null;
};

return items.map((item, index) => {
  const matchedIndex = pairedIndex(item, index);
  const lecture = matchedItems[matchedIndex]?.json || {};
  const response = item.json || {};
  const organizationUrl = usable(response.link?.webUrl);
  const itemUrl = usable(lecture.recording_web_url);
  const finalUrl = organizationUrl || itemUrl;

  return {
    json: {
      ...lecture,
      recording_url: finalUrl,
      recording_link_status: organizationUrl
        ? 'organization_view_link_created_exact_match'
        : (itemUrl
            ? 'drive_item_web_url_used_exact_match'
            : 'create_link_failed_no_update'),
      create_link_error: response.error?.message || null
    },
    pairedItem: { item: matchedIndex }
  };
});

return items.map((item, index) => ({
  json: {
    ...item.json,
    execution_result: 'NO_DATABASE_UPDATE_UNSAFE_OR_MISSING_MATCH'
  },
  pairedItem: { item: index }
}));

// Recording v9: lectures that failed the precheck. No Graph call, no update.
return items.map((item, index) => ({
  json: {
    ...item.json,
    recording_link_status: item.json.precheck_status,
    execution_result: 'NO_DATABASE_UPDATE_NOT_EVALUATED'
  },
  pairedItem: { item: index }
}));

// Recording v9: validate the operator's run settings. Fail closed.
//
// dry_run is disarmed ONLY by the literal boolean false. A missing value, the
// string "false", 0, null - anything else - keeps the run a dry run.
const raw = items[0]?.json || {};

const DATE = /^\d{4}-\d{2}-\d{2}$/;
function isoDate(name) {
  const value = String(raw[name] ?? '').trim();
  if (!DATE.test(value)) {
    throw new Error(`Run Settings: ${name} must be YYYY-MM-DD (got "${value}")`);
  }
  const parsed = new Date(value + 'T00:00:00Z');
  if (!Number.isFinite(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== value) {
    throw new Error(`Run Settings: ${name} is not a real calendar date (${value})`);
  }
  return value;
}

const dateFrom = isoDate('date_from');
const dateTo = isoDate('date_to');
if (dateFrom > dateTo) {
  throw new Error(`Run Settings: date_from ${dateFrom} is after date_to ${dateTo}`);
}
const spanDays = (Date.parse(dateTo) - Date.parse(dateFrom)) / 86400000;
if (spanDays > 366) {
  throw new Error(`Run Settings: date range of ${spanDays} days exceeds 366`);
}

const maxLectures = raw.max_lectures === undefined || raw.max_lectures === null ||
  raw.max_lectures === '' ? 100 : Number(raw.max_lectures);
if (!Number.isInteger(maxLectures) || maxLectures < 1 || maxLectures > 500) {
  throw new Error(`Run Settings: max_lectures must be an integer 1..500 (got "${raw.max_lectures}")`);
}

return [{
  json: {
    settings_version: 'recording_links_v9',
    dry_run: raw.dry_run !== false,
    date_from: dateFrom,
    date_to: dateTo,
    max_lectures: maxLectures
  }
}];
